// packagesInput names the capture shared by command and native-rule coverage.
var packagesInput = flag.String("packages-input", "", "Package capture runfile")

// packagesDiagram names the package diagram generated by the JSON-input rule.
var packagesDiagram = flag.String("packages-diagram", "", "Package diagram runfile")

// packagesRaster names the native dark render of the package diagram.
var packagesRaster = flag.String("packages-raster", "", "Package WebP runfile")

// packagesJSON names the aggregate JSON generated by the JSON-input rule.
var packagesJSON = flag.String("packages-json", "", "Package JSON runfile")

// packageEdgePattern accepts only uncaptioned directed or reciprocal links.
var packageEdgePattern = regexp.MustCompile(`^\s*(n[0-9]+) (-->|<-->) (n[0-9]+)$`)

// packageArtifact reads a declared runfile for command or pipeline verification.
func packageArtifact(t *testing.T, location string) (string, []byte) {
	t.Helper()
	path, err := runfiles.Rlocation(location)
	if err != nil {
		t.Fatal(err)
	}
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return path, content
}

// packageGraph checks independent counts and the complete expanded directed set.
func packageGraph(t *testing.T, output []byte, want map[string][2]int, edges []string, reciprocal int, totals string) {
	t.Helper()
	ids, nodes := map[string]string{}, map[string][2]int{}
	var ordered []string
	for caption := range want {
		ordered = append(ordered, caption)
	}
	slices.Sort(ordered)
	for index, match := range nodePattern.FindAllStringSubmatch(string(output), -1) {
		caption, _, _ := strings.Cut(match[2], "<br/>")
		counts, exists := want[caption]
		if _, duplicate := nodes[caption]; duplicate || !exists || index >= len(ordered) || caption != ordered[index] || match[1] != fmt.Sprintf("n%d", index) || match[2] != fmt.Sprintf("%s<br/>%d targets<br/>%d internal edges", caption, counts[0], counts[1]) {
			t.Fatalf("unexpected package node: %v", match)
		}
		ids[match[1]], nodes[caption] = caption, counts
	}
	if !maps.Equal(nodes, want) {
		t.Fatalf("package counts %v, want %v; diagram:\n%s", nodes, want, output)
	}
	var actual []string
	merged := 0
	for _, line := range strings.Split(string(output), "\n") {
		if !strings.Contains(line, "-->") {
			continue
		}
		match := packageEdgePattern.FindStringSubmatch(line)
		if match == nil || ids[match[1]] == "" || ids[match[3]] == "" || match[1] == match[3] {
			t.Fatalf("invalid package edge: %q", line)
		}
		actual = append(actual, ids[match[1]]+" -> "+ids[match[3]])
		if match[2] == "<-->" {
			actual = append(actual, ids[match[3]]+" -> "+ids[match[1]])
			merged++
		}
	}
	slices.Sort(actual)
	expected := slices.Clone(edges)
	slices.Sort(expected)
	if !slices.Equal(actual, expected) || merged != reciprocal {
		t.Fatalf("directed pairs %v, want %v; reciprocal=%d, want %d", actual, expected, merged, reciprocal)
	}
	for _, marker := range strings.Fields(totals) {
		if !regexp.MustCompile(`(?m)^%%[^\n]*\b` + regexp.QuoteMeta(marker) + `\b`).Match(output) {
			t.Fatalf("missing capture count %q: %s", marker, output)
		}
	}
}

// TestPackages verifies capture aggregation, filters, depth, and retained output.
func TestPackages(t *testing.T) {
	inputPath, input := packageArtifact(t, *packagesInput)
	output, err := command(t, string(input), "analyze", "package")
	if err != nil {
		t.Fatal(err)
	}
	nodes := map[string][2]int{"root": {2, 0}, "//tools": {2, 2}, "//projects": {1, 1}, "External": {2, 1}, "//external": {1, 0}, "//isolated": {1, 0}, "//root": {1, 0}, "//External": {1, 0}}
	edges := []string{"//tools -> //projects", "//projects -> //tools", "//tools -> root", "root -> //tools", "//tools -> External", "External -> //projects", "//projects -> //external", "//external -> External"}
	totals := "selected_targets=11 selected_edges=14 missing_references=2"
	packageGraph(t, output, nodes, edges, 2, totals)
	for _, marker := range []string{`"layout": "elk"`, `"nodePlacementStrategy": "NETWORK_SIMPLEX"`, `"mergeEdges": true`, "flowchart LR\n"} {
		if !bytes.Contains(output, []byte(marker)) {
			t.Fatalf("missing package layout %q: %s", marker, output)
		}
	}
	var comments string
	for _, line := range strings.Split(string(output), "\n") {
		if strings.HasPrefix(line, "%%") {
			comments += strings.ToLower(line) + "\n"
		}
	}
	for _, marker := range []string{"aggregate", "captur", "target", "reachability"} {
		if !strings.Contains(comments, marker) {
			t.Fatalf("missing aggregate disclosure %q: %s", marker, comments)
		}
	}
	records := strings.Split(strings.TrimSpace(string(input)), "\n")
	slices.Reverse(records)
	reordered, err := command(t, strings.Join(records, "\n"), "analyze", "package", "--input=-", "--output=-", "--package-depth=1", "--include-files=true", "--include-external=true", "--merge-reciprocal=true", "--format=mermaid")
	if err != nil || !bytes.Equal(output, reordered) {
		t.Fatalf("ordering or explicit defaults changed output: %v", err)
	}
	for _, direction := range []string{"LR", "RL", "TB", "BT"} {
		separate, err := command(t, string(input), "analyze", "package", "--direction="+direction, "--merge-reciprocal=false")
		if err != nil || !bytes.Contains(separate, []byte("flowchart "+direction+"\n")) {
			t.Fatalf("package direction %s: %v: %s", direction, err, separate)
		}
		packageGraph(t, separate, nodes, edges, 0, totals)
	}
	for _, selection := range []struct {
		// flags select file and repository exclusions.
		flags []string
		// omit lists expected groups removed by this selection.
		omit []string
		// edges enumerates every surviving directed package pair.
		edges []string
		// totals records independently counted capture statistics.
		totals string
		// reciprocal counts rendered double-headed connections.
		reciprocal int
	}{
		{[]string{"--include-files=false"}, []string{"root"}, []string{"//tools -> //projects", "//projects -> //tools", "//tools -> External", "External -> //projects", "//projects -> //external", "//external -> External"}, "selected_targets=9 selected_edges=11 missing_references=2", 1},
		{[]string{"--include-external=false"}, []string{"External"}, []string{"//tools -> //projects", "//projects -> //tools", "//tools -> root", "root -> //tools", "//projects -> //external"}, "selected_targets=9 selected_edges=10 missing_references=1", 2},
		{[]string{"--include-files=false", "--include-external=false"}, []string{"root", "External"}, []string{"//tools -> //projects", "//projects -> //tools", "//projects -> //external"}, "selected_targets=7 selected_edges=7 missing_references=1", 1},
	} {
		t.Run(strings.Join(selection.flags, ","), func(t *testing.T) {
			filtered, err := command(t, string(input), append([]string{"analyze", "package"}, selection.flags...)...)
			if err != nil {
				t.Fatal(err)
			}
			want := maps.Clone(nodes)
			for _, caption := range selection.omit {
				delete(want, caption)
			}
			packageGraph(t, filtered, want, selection.edges, selection.reciprocal, selection.totals)
		})
	}
	for _, depth := range []string{"2", "99"} {
		a := "//tools/a"
		if depth == "99" {
			a = "//tools/a/deep"
		}
		want := maps.Clone(nodes)
		delete(want, "//tools")
		delete(want, "//projects")
		want[a], want["//tools/b"], want["//projects/app"] = [2]int{1, 0}, [2]int{1, 0}, [2]int{1, 1}
		pairs := []string{a + " -> //tools/b", "//tools/b -> " + a, a + " -> //projects/app", "//tools/b -> //projects/app", "//projects/app -> " + a, a + " -> root", "root -> //tools/b", a + " -> External", "External -> //projects/app", "//projects/app -> //external", "//external -> External"}
		for _, merge := range []string{"true", "false"} {
			deeper, err := command(t, string(input), "analyze", "package", "--package-depth="+depth, "--merge-reciprocal="+merge)
			if err != nil {
				t.Fatal(err)
			}
			reciprocal := 0
			if merge == "true" {
				reciprocal = 2
			}
			packageGraph(t, deeper, want, pairs, reciprocal, totals)
		}
	}
	outputPath := filepath.Join(t.TempDir(), "packages.mmd")
	if stdout, err := command(t, "{", "analyze", "package", "--input="+inputPath, "--output="+outputPath); err != nil || len(stdout) != 0 {
		t.Fatalf("file conversion: %v: %s", err, stdout)
	}
	fileOutput, err := os.ReadFile(outputPath)
	if err != nil || !bytes.Equal(output, fileOutput) {
		t.Fatalf("file conversion differs: %v", err)
	}
	_, built := packageArtifact(t, *packagesDiagram)
	_, raster := packageArtifact(t, *packagesRaster)
	if !bytes.Equal(output, built) || len(raster) < 1000 || string(raster[:4]) != "RIFF" || string(raster[8:12]) != "WEBP" {
		t.Fatal("native package rule or dark WebP differs from verified command output")
	}
	if dir := os.Getenv("TEST_UNDECLARED_OUTPUTS_DIR"); dir != "" {
		report, err := json.MarshalIndent(map[string]any{"passed": true, "nodes": nodes, "directed_pairs": edges, "selected_targets": 11, "selected_edges": 14, "missing_references": 2}, "", "  ")
		if err != nil {
			t.Fatal(err)
		}
		for name, content := range map[string][]byte{"packages.mmd": output, "packages.dark.webp": raster, "packages-report.json": append(report, '\n')} {
			if err := os.WriteFile(filepath.Join(dir, name), content, 0o644); err != nil {
				t.Fatal(err)
			}
		}
	}
}

// TestPackageJSON checks the complete schema against independently counted data.
func TestPackageJSON(t *testing.T) {
	_, input := packageArtifact(t, *packagesInput)
	for _, selection := range []struct {
		// args selects depth and optional exclusions shared by both output formats.
		args []string
		// expected describes semantic JSON values, independent of its formatting.
		expected string
		// reciprocal counts the corresponding merged Mermaid connections.
		reciprocal int
	}{
		{[]string{"--package-depth=1"}, `{
  "groups": [
    {"caption":"//External","targetCount":1,"internalEdges":0,"members":["//External:local"]},
    {"caption":"//external","targetCount":1,"internalEdges":0,"members":["//external:bridge"]},
    {"caption":"//isolated","targetCount":1,"internalEdges":0,"members":["//isolated:alone"]},
    {"caption":"//projects","targetCount":1,"internalEdges":1,"members":["//projects/app:main"]},
    {"caption":"//root","targetCount":1,"internalEdges":0,"members":["//root:local"]},
    {"caption":"//tools","targetCount":2,"internalEdges":2,"members":["//tools/a/deep:main","//tools/b:make"]},
    {"caption":"External","targetCount":2,"internalEdges":1,"members":["@@two+//nested:lib","@one//:lib"]},
    {"caption":"root","targetCount":2,"internalEdges":0,"members":["//:generated","//:source"]}
  ],
  "edges": [
    {"source":1,"dependency":6,"targetEdges":1},
    {"source":3,"dependency":1,"targetEdges":1},
    {"source":3,"dependency":5,"targetEdges":1},
    {"source":5,"dependency":3,"targetEdges":2},
    {"source":5,"dependency":6,"targetEdges":1},
    {"source":5,"dependency":7,"targetEdges":2},
    {"source":6,"dependency":3,"targetEdges":1},
    {"source":7,"dependency":5,"targetEdges":1}
  ],
  "meta":{"packageDepth":1,"selectedTargets":11,"selectedEdges":14,"unresolvedReferences":2,"includeFiles":true,"includeExternal":true}
}`, 2},
		{[]string{"--package-depth=2"}, `{
  "groups": [
    {"caption":"//External","targetCount":1,"internalEdges":0,"members":["//External:local"]},
    {"caption":"//external","targetCount":1,"internalEdges":0,"members":["//external:bridge"]},
    {"caption":"//isolated","targetCount":1,"internalEdges":0,"members":["//isolated:alone"]},
    {"caption":"//projects/app","targetCount":1,"internalEdges":1,"members":["//projects/app:main"]},
    {"caption":"//root","targetCount":1,"internalEdges":0,"members":["//root:local"]},
    {"caption":"//tools/a","targetCount":1,"internalEdges":0,"members":["//tools/a/deep:main"]},
    {"caption":"//tools/b","targetCount":1,"internalEdges":0,"members":["//tools/b:make"]},
    {"caption":"External","targetCount":2,"internalEdges":1,"members":["@@two+//nested:lib","@one//:lib"]},
    {"caption":"root","targetCount":2,"internalEdges":0,"members":["//:generated","//:source"]}
  ],
  "edges": [
    {"source":1,"dependency":7,"targetEdges":1},
    {"source":3,"dependency":1,"targetEdges":1},
    {"source":3,"dependency":5,"targetEdges":1},
    {"source":5,"dependency":3,"targetEdges":1},
    {"source":5,"dependency":6,"targetEdges":1},
    {"source":5,"dependency":7,"targetEdges":1},
    {"source":5,"dependency":8,"targetEdges":2},
    {"source":6,"dependency":3,"targetEdges":1},
    {"source":6,"dependency":5,"targetEdges":1},
    {"source":7,"dependency":3,"targetEdges":1},
    {"source":8,"dependency":6,"targetEdges":1}
  ],
  "meta":{"packageDepth":2,"selectedTargets":11,"selectedEdges":14,"unresolvedReferences":2,"includeFiles":true,"includeExternal":true}
}`, 2},
		{[]string{"--include-files=false", "--include-external=false"}, `{
  "groups": [
    {"caption":"//External","targetCount":1,"internalEdges":0,"members":["//External:local"]},
    {"caption":"//external","targetCount":1,"internalEdges":0,"members":["//external:bridge"]},
    {"caption":"//isolated","targetCount":1,"internalEdges":0,"members":["//isolated:alone"]},
    {"caption":"//projects","targetCount":1,"internalEdges":1,"members":["//projects/app:main"]},
    {"caption":"//root","targetCount":1,"internalEdges":0,"members":["//root:local"]},
    {"caption":"//tools","targetCount":2,"internalEdges":2,"members":["//tools/a/deep:main","//tools/b:make"]}
  ],
  "edges": [{"source":3,"dependency":1,"targetEdges":1},{"source":3,"dependency":5,"targetEdges":1},{"source":5,"dependency":3,"targetEdges":2}],
  "meta":{"packageDepth":1,"selectedTargets":7,"selectedEdges":7,"unresolvedReferences":1,"includeFiles":false,"includeExternal":false}
}`, 1},
	} {
		t.Run(strings.Join(selection.args, ","), func(t *testing.T) {
			args := append([]string{"analyze", "package"}, selection.args...)
			output, err := command(t, string(input), append(slices.Clone(args), "--format=json")...)
			if err != nil {
				t.Fatal(err)
			}
			var actual, expected map[string]any
			if err := json.Unmarshal(output, &actual); err != nil {
				t.Fatal(err)
			}
			if err := json.Unmarshal([]byte(selection.expected), &expected); err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(actual, expected) {
				t.Fatalf("aggregate JSON %s, want semantic values %s", output, selection.expected)
			}
			separate, err := command(t, string(input), append(slices.Clone(args), "--format=json", "--merge-reciprocal=false")...)
			if err != nil || !bytes.Equal(output, separate) {
				t.Fatalf("reciprocal merge changed JSON: %v", err)
			}
			mermaid, err := command(t, string(input), args...)
			if err != nil {
				t.Fatal(err)
			}
			groups := actual["groups"].([]any)
			nodes := map[string][2]int{}
			for _, group := range groups {
				item := group.(map[string]any)
				nodes[item["caption"].(string)] = [2]int{int(item["targetCount"].(float64)), int(item["internalEdges"].(float64))}
			}
			var edges []string
			for _, edge := range actual["edges"].([]any) {
				item := edge.(map[string]any)
				source := groups[int(item["source"].(float64))].(map[string]any)["caption"].(string)
				dependency := groups[int(item["dependency"].(float64))].(map[string]any)["caption"].(string)
				edges = append(edges, source+" -> "+dependency)
			}
			meta := actual["meta"].(map[string]any)
			totals := fmt.Sprintf("selected_targets=%v selected_edges=%v missing_references=%v", meta["selectedTargets"], meta["selectedEdges"], meta["unresolvedReferences"])
			packageGraph(t, mermaid, nodes, edges, selection.reciprocal, totals)
			if slices.Equal(selection.args, []string{"--package-depth=1"}) {
				path, built := packageArtifact(t, *packagesJSON)
				if !strings.HasSuffix(path, ".json") || !bytes.Equal(output, built) {
					t.Fatal("native JSON rule differs from verified command output")
				}
				if dir := os.Getenv("TEST_UNDECLARED_OUTPUTS_DIR"); dir != "" {
					if err := os.WriteFile(filepath.Join(dir, "packages.json"), output, 0o644); err != nil {
						t.Fatal(err)
					}
				}
			}
		})
	}
}

// TestPackageCommandFailures verifies routing, safe failures, and escaped captions.
func TestPackageCommandFailures(t *testing.T) {
	_, input := packageArtifact(t, *packagesInput)
	for _, args := range [][]string{nil, {"--help"}, {"analyze"}, {"analyze", "--help"}} {
		output, err := command(t, "{", args...)
		if err != nil || !bytes.Contains(output, []byte("Usage:")) || !bytes.Contains(output, []byte("analyze")) {
			t.Fatalf("root help failed: %v: %s", err, output)
		}
	}
	for _, args := range [][]string{{"--root=//tools/a/deep:main"}, {"unknown-command"}, {"targets"}, {"packages"}, {"analyze", "unknown"}, {"analyze", "target", "--root=//tools/a/deep:main", "--package-depth=1"}} {
		if output, err := command(t, string(input), args...); err == nil || len(output) != 0 {
			t.Fatalf("invalid command accepted: %v: %v: %s", args, err, output)
		}
	}
	path := filepath.Join(t.TempDir(), "preserved.mmd")
	for _, invalid := range []struct {
		// input supplies malformed records or a valid capture for flag validation.
		input string
		// flags specifies unsupported package options and positional arguments.
		flags []string
	}{
		{"", nil},
		{"{", nil},
		{"[]", nil},
		{"{}", nil},
		{"null", nil},
		{string(input) + "{", nil},
		{string(input) + `{"type":"RULE","rule":{"name":"//tools/a/deep:main","ruleClass":"other"}}`, nil},
		{`{"type":"RULE","rule":{"name":"relative:target","ruleClass":"filegroup"}}`, nil},
		{`{"type":"RULE","rule":{"name":"//invalid:","ruleClass":"filegroup"}}`, nil},
		{string(input), []string{"--direction=invalid"}},
		{string(input), []string{"--unknown"}},
		{string(input), []string{"unexpected"}},
		{string(input), []string{"--root=//tools/a/deep:main"}},
		{string(input), []string{"--depth=1"}},
		{string(input), []string{"--package-depth=0"}},
		{string(input), []string{"--package-depth=-1"}},
		{string(input), []string{"--package-depth=invalid"}},
		{string(input), []string{"--format=invalid"}},
	} {
		for _, existing := range []bool{false, true} {
			if existing {
				if err := os.WriteFile(path, []byte("preserve\n"), 0o644); err != nil {
					t.Fatal(err)
				}
			} else if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
				t.Fatal(err)
			}
			args := append([]string{"analyze", "package", "--output=" + path}, invalid.flags...)
			if output, err := command(t, invalid.input, args...); err == nil || len(output) != 0 {
				t.Fatalf("invalid package input accepted: %v: %v: %s", args, err, output)
			}
			content, err := os.ReadFile(path)
			if (existing && (err != nil || string(content) != "preserve\n")) || (!existing && !os.IsNotExist(err)) {
				t.Fatalf("invalid conversion modified output: existing=%t, %v, %q", existing, err, content)
			}
		}
	}
	hostile := `{"type":"RULE","rule":{"name":"//quote\"<b>&#35;[x]%%{init}/nested:leaf","ruleClass":"filegroup"}}`
	escaped, err := command(t, hostile, "analyze", "package")
	if err != nil || bytes.Contains(escaped, []byte("<b>")) || !bytes.Contains(escaped, []byte("#34;")) || !bytes.Contains(escaped, []byte("#38;#35;")) || bytes.Count(escaped, []byte("%%{init")) != 1 || len(nodePattern.FindAllSubmatch(escaped, -1)) != 1 {
		t.Fatalf("unsafe package caption: %v: %s", err, escaped)
	}
}
